// Main browser runtime. The data catalogue is loaded first from cases.js.
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const telemetry=(name,detail={})=>{
  const payload={event:name,build:'3.8.0',ts:Date.now(),...detail};
  try{window.dispatchEvent(new CustomEvent('daria:telemetry',{detail:payload}))}catch{}
  window.dataLayer=window.dataLayer||[];window.dataLayer.push(payload);
  try{const log=JSON.parse(localStorage.getItem('daria.telemetry')||'[]');log.push(payload);localStorage.setItem('daria.telemetry',JSON.stringify(log.slice(-80)))}catch{}
};

const TOOLS=[['Ask',0],['Check',0],['Compare',80],['Test',160],['Counterexample',320],['Check incentives',500],['Split hypothesis',720],['Verify independence',980]];
const safeJSON=(v,f)=>{try{return JSON.parse(v)}catch{return f}};const state={xp:+localStorage.getItem('daria.game.xp')||0,streak:+localStorage.getItem('daria.game.streak')||0,history:safeJSON(localStorage.getItem('daria.game.history')||'[]',[])};
function persist(){localStorage.setItem('daria.game.xp',state.xp);localStorage.setItem('daria.game.streak',state.streak);localStorage.setItem('daria.game.history',JSON.stringify(state.history.slice(0,8)));renderProfile()}
function level(){return Math.max(1,Math.floor(state.xp/180)+1)}
function renderProfile(){
  const streak=$('#homeStreak'),history=$('#homeHistory');
  if(streak){if(state.streak>1){streak.hidden=false;streak.textContent=`✦ ${state.streak} streak`}else streak.hidden=true}
  if(history){history.textContent=state.history.length?`Last case · ${state.history[0].title}`:'No solved cases yet.'}
}
function renderHomeCase(){
  const c=chooseCase();
  window.__homeCase=c;
  $('#homeDomain').textContent=c.domain;
  $('#homeArchetype').textContent=c.archetype;
  $('#homeCaseTitle').textContent=c.title;
  $('#homeCasePrompt').textContent=c.prompt;
}
function show(id){$$('.screen').forEach(x=>x.classList.remove('active'));$('#'+id).classList.add('active');scrollTo({top:0,behavior:'auto'})}$$('[data-home]').forEach(b=>b.onclick=()=>show('home'));
function dots(n,used){return Array.from({length:n},(_,i)=>`<span class="moveDot ${i<used?'used':''}"></span>`).join('')}
function chooseCase(exclude){const requested=new URLSearchParams(location.search).get('case');if(requested){const exact=CASES.find(c=>c.id===requested);if(exact)return exact}let pool=CASES.filter(c=>c.id!==exclude);return pool[Math.floor(Math.random()*pool.length)]}
const DARIA={good:'Good. That move can actually change the decision.',weak:'Not useless, but it leaves the central uncertainty mostly intact.',bad:'You spent commitment before buying enough information.',contradiction:'Nice. Something just stopped fitting the first story.',insight:'That evidence separates the stories. Now the next move should change.',over:'You know enough. More research is starting to cost more than it teaches.'};

let qCase=null,qTurn=0,qScores=[],qUsed=[],qClues=[],qPressure=0,qLast=null;
const ACTION_META={
 Ask:{label:'Ask',cost:1,side:'They know you are looking',tone:'social'},
 Check:{label:'Check',cost:1,side:'Time passes while you verify',tone:'quiet'},
 Compare:{label:'Compare',cost:1,side:'You narrow the field, not the outcome',tone:'analytic'},
 Test:{label:'Test',cost:1,side:'The system changes while you learn',tone:'risky'}
};
function startQuick(c=null){
 qCase=c||chooseCase(qCase?.id);telemetry('case_start',{mode:'quick',case_id:qCase.id});qTurn=0;qScores=[];qUsed=[];qClues=[];qPressure=0;qLast=null;
 $('#quickDomain').textContent=qCase.domain;$('#quickArchetype').textContent=qCase.archetype;
 $('#quickTitle').textContent=qCase.title;$('#quickPrompt').textContent=qCase.prompt;
 renderQuick();show('quick')
}
function quickActionValue(a){
 const x=qCase.actions[a];
 const quality=x.quality==='high'?2:x.quality==='medium'?1:0;
 const novelty=qClues.some(c=>c.target===x.target)?0:1;
 return quality+novelty;
}
function renderQuick(reveal=null){
 const max=3, remaining=max-qTurn;
 $('#quickTurnLabel').textContent=remaining>0?`${remaining} move${remaining===1?'':'s'} left`:'Decision time';
 $('#quickDots').innerHTML=dots(max,qTurn);
 const stage=$('#quickStage');
 if(reveal){
   const meta=ACTION_META[reveal.action];
   const tension=reveal.action==='Test'?'State changed':reveal.action==='Ask'?'Actor alerted':reveal.action==='Compare'?'Reference narrowed':'Fact verified';
   $('#quickChar').dataset.state=reveal.direction==='contradicts'?'contradiction':'skeptical';
   stage.innerHTML=`<div class="quickBoard">
     <div class="quickReveal">
       <div class="eyebrow">${meta.label.toUpperCase()} → NEW INFORMATION</div>
       <div class="event">${reveal.evidence}</div>
       <div class="worldShift"><span>${tension}</span><span>${meta.side}</span></div>
       <div class="dariaLine">Daria: “Useful. But what does it rule out?”</div>
     </div>
     <div class="quickControls">
       ${qTurn<max?'<button class="secondaryBtn" id="continueQuick">Keep digging</button>':''}
       <button class="primaryBtn" id="callQuick">Decide now</button>
     </div>
   </div>`;
   if(qTurn<max)$('#continueQuick').onclick=()=>renderQuick();
   $('#callQuick').onclick=()=>renderQuickCall();
   return;
 }
 if(qTurn>=max){renderQuickCall();return}
 const actions=Object.keys(qCase.actions);
 stage.innerHTML=`<div class="quickBoard">
   <div class="boardTop"><div><div class="eyebrow">CASE BOARD</div><strong>Choose where to spend the next move.</strong></div>
   <div class="pressure" aria-label="moves spent">${Array.from({length:max},(_,i)=>`<i class="${i<qTurn?'on':''}"></i>`).join('')}</div></div>
   <div class="clueRail">${Array.from({length:3},(_,i)=>qClues[i]?`<div class="clueSlot filled"><b>Clue ${i+1}</b>${qClues[i].evidence}</div>`:`<div class="clueSlot">Unknown</div>`).join('')}</div>
   <div class="actionDeck">${actions.map(a=>{const x=qCase.actions[a],m=ACTION_META[a]||{label:a,cost:1,side:''};return `<button class="actionCard ${qUsed.includes(a)?'used':''} ${a==='Test'?'risky':''}" data-action="${a}" ${qUsed.includes(a)?'disabled':''}>
      <span class="actionType">${m.label}</span><strong>${x.text}</strong><span class="actionCost">costs 1 move</span>
   </button>`}).join('')}</div>
   ${qTurn>0?'<button class="secondaryBtn" id="callQuick">Decide with what you know</button>':''}
 </div>`;
 stage.querySelectorAll('.actionCard:not([disabled])').forEach(b=>b.onclick=()=>takeQuickAction(b.dataset.action));
 if($('#callQuick'))$('#callQuick').onclick=()=>renderQuickCall();
}
function takeQuickAction(a){
 if(qTurn>=3||qUsed.includes(a))return;
 const x=qCase.actions[a],value=quickActionValue(a);
 qUsed.push(a);qTurn++;qPressure+=a==='Test'?2:a==='Ask'?1:0;
 qClues.push({...x,action:a});
 qScores.push({action:a,value,quality:x.quality,direction:x.direction,target:x.target});
 state.xp+=Math.max(4,value*7);persist();
 renderQuick({...x,action:a});
}
function renderQuickCall(){
 const stage=$('#quickStage');
 $('#quickTurnLabel').textContent='Make the call';
 stage.innerHTML=`<div class="quickBoard">
   <div class="boardTop"><div><div class="eyebrow">YOUR CALL</div><strong>No answer is risk-free. Commit when the evidence is enough.</strong></div></div>
   <div class="clueRail">${Array.from({length:3},(_,i)=>qClues[i]?`<div class="clueSlot filled"><b>Clue ${i+1}</b>${qClues[i].evidence}</div>`:`<div class="clueSlot">Unspent move</div>`).join('')}</div>
   <div class="quickCallGrid">${qCase.callOptions.map((o,i)=>`<button class="quickCall" data-call="${i}"><strong>${o.label}</strong></button>`).join('')}</div>
   ${qTurn<3?'<button class="secondaryBtn" id="backToBoard">Spend another move</button>':''}
 </div>`;
 $$('.quickCall').forEach(b=>b.onclick=()=>finishQuick(+b.dataset.call));
 if($('#backToBoard'))$('#backToBoard').onclick=()=>renderQuick();
}
function finishQuick(callIndex){
 const call=qCase.callOptions[callIndex],best=call.grade==='best';
 const useful=qScores.filter(x=>x.value>=2).length;
 const diversity=new Set(qScores.map(x=>x.target)).size;
 const overcommit=qPressure;
 const quality=Math.max(0,Math.min(100,38+useful*14+diversity*9+(best?22:0)-overcommit*4));
 state.xp+=best?35:8;state.streak=best&&useful>=1?state.streak+1:0;persist();
 finishCase({
   title:best?'Defensible call.':'Plausible — but exposed.',
   text:qCase.lesson,
   scores:[['Decision quality',quality+'%'],['Signals used',String(qClues.length)],['Coverage',diversity>=2?'Broad':'Narrow'],['Commitment',overcommit>=2?'High':'Controlled']],
   daria:best?(qTurn<3?'You stopped before certainty. Good. Certainty was not for sale.':'You earned the call; the last move was optional.'):
   'The move was plausible. The debrief is about what your evidence could and could not support.',
   case:qCase,mode:'quick',call:call.label,trace:qClues.map(x=>({action:x.action,evidence:x.evidence,direction:x.direction,target:x.target}))
 })
}
let inv=null,invMoves=0,invEvidence=[],hypState={},lastEvidence=null,classified=false;
function startInvestigation(c=null){inv=c||chooseCase(inv?.id);telemetry('case_start',{mode:'investigation',case_id:inv.id});invMoves=0;invEvidence=[];lastEvidence=null;classified=false;hypState={};inv.hypotheses.forEach(h=>hypState[h.id]={score:1});$('#invDomain').textContent=inv.domain;$('#invArchetype').textContent=inv.archetype;$('#invTitle').textContent=inv.title;$('#invPrompt').textContent=inv.prompt;$('#evidenceArea').innerHTML='';$('#makeCallBtn').textContent='Make a call';renderInvestigation();show('investigation')}
function renderInvestigation(){const max=5;$('#movesLeft').textContent=`${max-invMoves} move${max-invMoves===1?'':'s'} left`;$('#invDots').innerHTML=dots(max,invMoves);const arr=inv.hypotheses.map(h=>({...h,...hypState[h.id]})).sort((a,b)=>b.score-a.score),lead=arr[0]?.id;$('#hypGrid').innerHTML=arr.map(h=>`<div class="hyp ${h.id===lead&&h.score>1?'leading':''} ${h.score<.7?'weakened':''} ${h.score<.42?'broken':''}" data-hyp="${h.id}"><strong>${h.label}</strong><div class="hypState">${h.id===lead&&h.score>1?'leading':h.score<.42?'nearly eliminated':h.score<.7?'weakened':'plausible'}</div></div>`).join('');const allowed=['Ask','Check',...(state.xp>=80?['Compare']:[]),...(state.xp>=160?['Test']:[])];$('#actionRow').innerHTML=['Ask','Check','Compare','Test'].map(a=>`<button class="actionBtn ${allowed.includes(a)?'':'locked'}" data-action="${a}" ${(!allowed.includes(a)||invMoves>=max||!!lastEvidence)?'disabled':''}>${a}${!allowed.includes(a)?' 🔒':''}</button>`).join('');$$('#actionRow .actionBtn:not([disabled])').forEach(b=>b.onclick=()=>takeInvAction(b.dataset.action));if(invMoves>=4&&!lastEvidence)$('#invChar').dataset.state='ready'}
function applyEvidence(x){const h=hypState[x.target];if(x.direction==='supports')h.score*=x.quality==='high'?1.72:1.35;else h.score*=x.quality==='high'?.40:.68}
function takeInvAction(a){if(invMoves>=5||lastEvidence)return;const x=inv.actions[a];invMoves++;lastEvidence={...x,action:a};invEvidence.push(lastEvidence);applyEvidence(x);renderInvestigation();renderEvidence(lastEvidence)}
function renderEvidence(x){const area=$('#evidenceArea');const contradiction=x.direction==='contradicts';$('#invChar').dataset.state=contradiction?'contradiction':'investigating';$('#invChar img').src=contradiction?'data:image/webp;base64,':'data:image/webp;base64,';area.innerHTML=`<div class="evidenceCard ${contradiction?'contradiction':''}" id="evidenceCard" tabindex="0"><div class="eyebrow">${x.action} → EVIDENCE · ${x.quality.toUpperCase()} RELIABILITY</div><h3>${x.text}</h3><p>${x.evidence}</p><div class="swipeHint"><span>← contradicts</span><span>↓ weak</span><span>supports →</span></div><div class="classify"><button data-rate="contradicts">← Contradicts</button><button data-rate="irrelevant">↓ Weak / irrelevant</button><button data-rate="supports">Supports →</button></div></div><div class="daria"><div class="miniFace"><img src="${contradiction?'data:image/webp;base64,':'data:image/webp;base64,'}" alt="Daria"></div><div>${contradiction?DARIA.contradiction:'Classify the evidence before you spend another move.'}</div></div>`;const card=$('#evidenceCard');let sx=0,sy=0,dragging=false;card.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;dragging=true;sx=e.clientX;sy=e.clientY;card.setPointerCapture(e.pointerId);card.classList.add('dragging')});card.addEventListener('pointerup',e=>{if(!dragging)return;dragging=false;card.classList.remove('dragging');const dx=e.clientX-sx,dy=e.clientY-sy;if(Math.abs(dx)>70||Math.abs(dy)>70)classify(Math.abs(dx)>Math.abs(dy)?(dx>0?'supports':'contradicts'):'irrelevant')});document.querySelectorAll('[data-rate]').forEach(b=>{b.onpointerdown=e=>e.stopPropagation();b.onpointerup=e=>e.stopPropagation();b.onclick=e=>{e.stopPropagation();classify(b.dataset.rate)}})}
function classify(rate){if(classified||!lastEvidence)return;classified=true;const good=rate===lastEvidence.direction;state.xp+=good?22:4;state.streak=good?state.streak+1:0;persist();$('#evidenceArea').querySelector('.classify').innerHTML=`<small style="color:${good?'var(--good)':'var(--warn)'}">${good?'Good read. The evidence direction matches the case.':'Not quite. Re-read what changed and which explanation it bears on.'}</small>`;$('#invChar').dataset.state=good?'insight':'skeptical';setTimeout(()=>{lastEvidence=null;classified=false;$('#evidenceArea').innerHTML='';renderInvestigation()},550)}
$('#makeCallBtn').onclick=()=>{const area=$('#evidenceArea');area.innerHTML=`<div class="reveal"><div class="eyebrow">MAKE THE CALL</div><strong>What do you do with what you know now?</strong></div><div class="finalChoices">${inv.callOptions.map((o,i)=>`<button class="call" data-call="${i}"><strong>${o.label}</strong></button>`).join('')}</div>`;$$('[data-call]').forEach(b=>b.onclick=()=>{const o=inv.callOptions[+b.dataset.call],useful=invEvidence.filter(e=>e.quality==='high').length,g=o.grade;state.xp+=g==='best'?75:g==='weak'?20:4;state.streak=g==='best'?state.streak+1:0;persist();finishCase({title:g==='best'?'Strong call.':g==='weak'?'Defensible, but inefficient.':'You acted against the evidence.',text:inv.lesson,scores:[['Evidence quality',useful>=3?'A':useful>=2?'B':'C'],['Moves used',String(invMoves)],['Call',g==='best'?'A':g==='weak'?'C':'D'],['Residual risk',g==='best'?'Low':'Medium'],],daria:g==='best'?(invMoves<5?'You stopped before the move budget ran out. That is a feature, not a failure.':DARIA.insight):DARIA[g==='bad'?'bad':'weak'],case:inv,mode:'investigation',call:o.label,trace:invEvidence.map(x=>({action:x.action,evidence:x.evidence,direction:x.direction,target:x.target}))})})};
function finishCase(r){
 state.history.unshift({id:r.case.id,domain:r.case.domain,title:r.case.title});
 state.history=state.history.filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i).slice(0,8);
 persist();
 $('#resultTitle').textContent=r.title;
 $('#resultText').textContent=r.text;
 $('#scoreGrid').innerHTML=r.scores.map(([k,v])=>`<div class="score"><b>${v}</b><small>${k}</small></div>`).join('');
 $('#resultDaria').textContent=r.daria;
 const trace=(r.trace||[]).slice(0,5);
 $('#consequenceChain').innerHTML=[
   ...trace.map((x,i)=>`<div class="consequenceStep"><b>${i===0?'You did':'Then'}</b><span><strong>${x.action}</strong> → ${x.evidence}</span></div>`),
   `<div class="consequenceStep final"><b>Your call</b><span>${r.call||'Decision committed'} → ${r.text}</span></div>`
 ].join('');
 const unlocked=TOOLS.filter(([t,x])=>state.xp>=x&&state.xp-(r.case?20:0)<x);
 $('#unlockResult').innerHTML=unlocked.length?`<div class="unlockCard"><strong>Tool unlocked</strong><br>${unlocked.map(x=>x[0]).join(', ')}</div>`:'';
 telemetry('case_complete',{mode:r.mode||'unknown',case_id:r.case.id,moves:trace.length,call:r.call||'',title:r.title});
 show('result')
}
$('#quickMode').onclick=()=>startQuick(window.__homeCase||null);$('#investigationMode').onclick=()=>startInvestigation(window.__homeCase||null);$('#playAgain').onclick=()=>{telemetry('case_restart',{from:'result',mode:'quick'});startQuick()};
$('#deepFromResult').onclick=()=>{telemetry('case_restart',{from:'result',mode:'investigation'});startInvestigation()};
$('#shareResult').onclick=async()=>{
 const text=[document.title,$('#resultTitle').textContent,$('#resultText').textContent].filter(Boolean).join(' — ');
 let method='none';
 try{
   if(navigator.share){await navigator.share({title:'DARIA.EXE',text,url:location.origin+location.pathname});method='native'}
   else if(navigator.clipboard){await navigator.clipboard.writeText(text+' '+location.origin+location.pathname);method='clipboard';$('#shareResult').textContent='Copied'}
 }catch{method='cancelled'}
 telemetry('result_share',{method});
};if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js?v=3.8.0-split').catch(()=>{});renderProfile();renderHomeCase();
